import app from 'flarum/admin/app';
import { extend } from 'flarum/common/extend';
import { EXT, t } from './state';
export { default as extend } from './extend';
app.initializers.add(EXT, () => {
  // Member Desk's member page gets a "Permissions" button, through its heroActions hook.
  if (!('ernestdefoe-member-desk' in flarum.extensions)) return;
  extend('ext:ernestdefoe/member-desk/common/MemberView', 'heroActions', function (items) {
    const id = this.attrs?.id;
    if (!id) return;
    items.add('permissions', m("a", {
      className: "Button",
      href: '#' + app.route('permissionDesk.member', {
        id
      })
    }, m("i", {
      "aria-hidden": "true",
      className: "icon fas fa-key Button-icon"
    }), m("span", {
      className: "Button-label"
    }, t('member_desk_button'))), -10);
  });
});