import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import extractText from 'flarum/common/utils/extractText';
import { t } from './state';
import { tagItems, tagMatches, tagName } from './rows';
const LIMIT = 200;

/**
 * Pick one tag out of hundreds: a button that opens a search box over the tag tree (children
 * under their parent). Type to filter by name or "Parent › Child", arrows + Enter to pick.
 */
export default class TagPicker extends Component {
  open = false;
  q = '';
  active = 0;
  focus = false;
  outside = e => {
    if (this.open && !this.element.contains(e.target)) {
      this.open = false;
      m.redraw();
    }
  };
  oncreate(vnode) {
    super.oncreate(vnode);
    document.addEventListener('mousedown', this.outside);
  }
  onremove(vnode) {
    super.onremove(vnode);
    document.removeEventListener('mousedown', this.outside);
  }
  onupdate(vnode) {
    super.onupdate(vnode);
    if (this.focus) {
      this.focus = false;
      this.element.querySelector('.PermissionDesk-pickerPop input')?.focus();
    }
    if (this.open) this.element.querySelector('.PermissionDesk-pickerPop .is-active')?.scrollIntoView({
      block: 'nearest'
    });
  }
  options() {
    const a = this.attrs;
    const q = this.q.trim().toLowerCase();
    const out = [];
    if (a.global && (!q || extractText(t('scope.global')).toLowerCase().includes(q))) out.push({
      id: 'global',
      text: extractText(t('scope.global')),
      depth: 0,
      item: null
    });
    const restricted = new Set(tagItems().filter(i => i.restricted).map(i => i.id));
    tagItems().forEach(i => {
      if (a.restricted && !i.restricted) return;
      if (a.exclude?.includes(i.id)) return;
      if (q && !tagMatches(i.path, q)) return;
      // In the tree view, a child whose parent isn't listed shows its full path instead.
      const parentListed = !!i.parentId && (!a.restricted || restricted.has(i.parentId));
      out.push({
        id: i.id,
        text: q || !parentListed ? i.path : i.name,
        depth: q || !parentListed ? 0 : i.depth,
        item: i
      });
    });
    return out;
  }
  pick(id) {
    this.open = false;
    this.q = '';
    this.attrs.onchange(id);
  }
  view() {
    const a = this.attrs;
    const current = a.value === 'global' ? extractText(t('scope.global')) : a.value ? tagName(a.value) : a.placeholder || '';
    const color = a.value && a.value !== 'global' ? tagItems().find(i => i.id === a.value)?.tag.attribute('color') : null;
    return m("div", {
      className: 'PermissionDesk-picker' + (this.open ? ' is-open' : '')
    }, m("button", {
      type: "button",
      className: "FormControl PermissionDesk-pickerBtn",
      "aria-haspopup": "listbox",
      "aria-expanded": this.open ? 'true' : 'false',
      "aria-label": `${a.label}: ${current}`,
      onclick: () => {
        this.open = !this.open;
        this.q = '';
        this.active = 0;
        this.focus = this.open;
      }
    }, color ? m("span", {
      className: "PermissionDesk-tagDot",
      style: {
        background: color
      }
    }) : null, m("span", {
      className: 'PermissionDesk-pickerText' + (a.value ? '' : ' PermissionDesk-muted')
    }, current), m(Icon, {
      name: "fas fa-caret-down"
    })), this.open ? this.popover() : null);
  }
  popover() {
    const all = this.options();
    const list = all.slice(0, LIMIT);
    if (this.active >= list.length) this.active = Math.max(0, list.length - 1);
    return m("div", {
      className: "PermissionDesk-pickerPop"
    }, m("input", {
      className: "FormControl",
      type: "search",
      value: this.q,
      placeholder: extractText(t('picker.search')),
      "aria-label": extractText(t('picker.search')),
      oninput: e => {
        this.q = e.target.value;
        this.active = 0;
      },
      onkeydown: e => this.keydown(e, list)
    }), m("ul", {
      role: "listbox",
      "aria-label": this.attrs.label
    }, list.map((o, i) => this.option(o, i))), !list.length ? m("div", {
      className: "PermissionDesk-muted PermissionDesk-pickerEmpty"
    }, t('picker.none')) : null, all.length > LIMIT ? m("div", {
      className: "PermissionDesk-muted PermissionDesk-pickerEmpty"
    }, t('picker.more', {
      count: all.length - LIMIT
    })) : null);
  }
  keydown(e, list) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      this.active = Math.min(this.active + 1, list.length - 1);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      this.active = Math.max(this.active - 1, 0);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (list[this.active]) this.pick(list[this.active].id);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      this.open = false;
      this.element.querySelector('.PermissionDesk-pickerBtn')?.focus();
    }
  }
  option(o, i) {
    const a = this.attrs;
    return m("li", {
      role: "option",
      "aria-selected": o.id === a.value ? 'true' : 'false',
      className: (i === this.active ? 'is-active' : '') + (o.id === a.value ? ' is-current' : ''),
      style: {
        paddingLeft: 10 + o.depth * 16 + 'px'
      },
      onmousedown: e => e.preventDefault(),
      onclick: () => this.pick(o.id)
    }, o.item ? m("span", {
      className: "PermissionDesk-tagDot",
      style: {
        background: o.item.tag.attribute('color') || 'var(--pd-faint)'
      }
    }) : null, m("span", null, o.text));
  }
}